 for(auto&m:parsed.mods){auto dir=mods/fs::u8path(m.name);string meta;std::error_code ec;if(fs::exists(nativePath(dir/"meta.ini"),ec))meta=readFile(nativePath(dir/"meta.ini"));
 try{for(auto&e:directoryItems(dir)){auto n=low(e.path.filename().u8string());if(e.directory||e.link||!isPlugin(n))continue;if(m.state=='+')available[n]={e.path,m.name,meta};else disabled[n]=m.name;}
 if(m.state=='+'){auto plugdir=dir/"SKSE"/"Plugins";if(fs::is_directory(nativePath(plugdir),ec))for(auto&e:directoryItems(plugdir))if(!e.directory&&!e.link){auto n=low(e.path.filename().u8string());if(ends(n,".dll"))dlls.push_back({e.path,m.name,meta});if(ends(n,".bin"))addressFiles.insert(n);}}
 }catch(const std::exception&e){add("LEITURA INCOMPLETA",m.name,e.what());}}
 auto plugins=profile.parent_path()/"plugins.txt";std::error_code ec;bool hasList=fs::exists(nativePath(plugins),ec);
 if(hasList){for(auto&l:lines(readFile(nativePath(plugins)))){auto t=trim(l);if(!t.empty()&&t[0]=='*')active.insert(low(trim(t.substr(1))));}}else add("NAO VERIFICADO","plugins.txt","Arquivo ausente. Serao conferidas dependencias dos plugins disponiveis, sem afirmar que estao ativos.");
