 for(size_t i=0;i<queue.size();i++){auto found=available.find(queue[i]);if(found==available.end())continue;try{for(auto&m:readMasters(found->second.path)){auto n=low(m);if(reachable.insert(n).second)queue.push_back(n);}}catch(...){} }
 for(auto&n:active)if(!available.count(n))add("AUSENTE",n,"Plugin marcado como ativo, mas seu arquivo nao foi encontrado nos mods ativos nem em Data. Verifique overwrite e caminhos externos.",searchMod(n,version),"Origem nao identificada");
 for(auto&[name,p]:available){if(hasList&&!reachable.count(name))continue;try{auto masters=readMasters(p.path);d.checked++;for(auto&m:masters){auto n=low(m);if(!available.count(n)){if(disabled.count(n))add("MOD DESATIVADO",m,"Exigido por "+name+". Encontrado no mod desativado: "+disabled[n]+". Revise e ative no MO2; nao precisa baixar outra copia.");else if(data.empty())add("NAO VERIFICADO",m,"Exigido por "+name+". Nao encontrado nos mods ativos; Data ainda nao foi informada.");else add("AUSENTE",m,"Exigido por "+name+" ("+p.mod+"). Nao encontrado nos caminhos conferidos. A pesquisa e por nome de arquivo; confirme o mod correto e seus requisitos.",masterPage(m,version),masterPage(m,version)==searchMod(m,version)?"Origem nao identificada":"Abrir mod necessario");}else if(hasList&&!active.count(n))add("PLUGIN DESATIVADO",m,"Exigido por "+name+". Arquivo instalado em "+available[n].mod+". Ative o plugin no painel direito do MO2 e rode o LOOT.");}}catch(const std::exception&e){add("LEITURA INCOMPLETA",name,e.what());}}
 auto runtime=version;if(ends(runtime,".0"))runtime.resize(runtime.size()-2);
